"""
SortedSet (重複なし集合 / 平衡二分木代替 / std::set)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
重複なしの要素を常にソート順で管理する平衡二分木代替データ構造 (C++の std::set 相当)。
外部ライブラリ非依存で √N バケット分割により高速に動作。

【サポート操作】
- add(x): 要素 x を追加 (存在すれば何もしない, O(√N))
- discard(x): 要素 x を削除 (存在すれば True, O(√N))
- __contains__(x): x が存在するか判定 (O(log N))
- index(x): x 以上の最小インデックス (bisect_left 相当, O(log N))
- __getitem__(i): i 番目に小さい要素を取得 (O(√N))
- __len__(): 要素数 (O(1))
"""

import math
from bisect import bisect_left, bisect_right

# https://github.com/ddfkit/acsampl/blob/main/sortedset.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class SortedSet:
    BUCKET_RATIO=16;SPLIT_RATIO=24
    def __init__(self,a=[]):
        a=sorted(set(a));n=self.size=len(a)
        num=int(math.ceil(math.sqrt(n/self.BUCKET_RATIO))) or 1
        self.a=[a[n*i//num:n*(i+1)//num] for i in range(num)]
    def __len__(self):return self.size
    def _pos(self,x):
        for i,bk in enumerate(self.a):
            if x<=bk[-1]:break
        return bk,i,bisect_left(bk,x)
    def __contains__(self,x):
        if not self.size:return False
        bk,_,i=self._pos(x)
        return i<len(bk) and bk[i]==x
    def add(self,x):
        if not self.size:self.a=[[x]];self.size=1;return True
        bk,i,idx=self._pos(x)
        if idx<len(bk) and bk[idx]==x:return False
        bk.insert(idx,x);self.size+=1
        if len(bk)>len(self.a)*self.SPLIT_RATIO:
            mid=len(bk)>>1
            self.a.insert(i+1,bk[mid:]);del bk[mid:]
        return True
    def discard(self,x):
        if not self.size:return False
        bk,i,idx=self._pos(x)
        if idx==len(bk) or bk[idx]!=x:return False
        bk.pop(idx);self.size-=1
        if not bk:del self.a[i]
        return True
    def index(self,x):
        ans=0
        for bk in self.a:
            if bk[-1]>=x:return ans+bisect_left(bk,x)
            ans+=len(bk)
        return ans
    def __getitem__(self,i):
        if i<0:i+=self.size
        for bk in self.a:
            if i<len(bk):return bk[i]
            i-=len(bk)
        raise IndexError

if __name__ == "__main__":
    s = SortedSet([5, 3, 1, 3, 5])
    assert len(s) == 3
    assert s[0] == 1 and s[1] == 3 and s[2] == 5
    assert 3 in s and 4 not in s
    s.add(4)
    assert s.index(4) == 2
    s.discard(3)
    assert 3 not in s and len(s) == 3
    print("sortedset.py: tests passed!")
